// <auto-generated/> Roslyn incremental generator implementation for DKNet.SlimBus.Generators.

using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Globalization;
using System.Linq;
using System.Text;
using System.Threading;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace DKNet.SlimBus.Generators;

#nullable enable

/// <summary>
/// Incremental source generator that discovers entities carrying <c>[CrudCreate]</c>/<c>[CrudUpdate]</c>
/// members and emits a Create/Update request record for each, implementing the SlimBus request contracts.
/// Handler and endpoint emission are added by later generators layered on the same pipeline.
/// </summary>
[Generator]
public sealed class CrudGenerator : IIncrementalGenerator
{
    /// <summary>
    /// Registers the compilation-driven pipeline: build the CRUD model for every compilation, then emit
    /// request records and diagnostics for it.
    /// </summary>
    /// <param name="context">The generator initialization context.</param>
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var results = context.CompilationProvider.Select(static (compilation, ct) => CrudModelBuilder.Build(compilation, ct));
        context.RegisterSourceOutput(results, static (spc, result) => Emitter.Emit(spc, result));
    }
}

/// <summary>
/// Diagnostic descriptors reported by <see cref="CrudModelBuilder"/>.
/// </summary>
